  k8sNodeGroupAutoscalingOption,
  k8sNodeGroupDescriptionOption,
  k8sNodeGroupMaxOption,
  k8sNodeGroupMinOption,
  k8sNodeGroupTagOption,
} from './k8s.options.js';

export const k8sNodeGroupsCreateCommand = defineCommand({
  description: 'Create a node group on a Kubernetes cluster',
  since: null,
  options: {
    flavor: defineOption({
      name: 'flavor',
      schema: z.string().transform((v) => v.toUpperCase()),
      description: 'Flavor of the nodes',
      placeholder: 'flavor',
      complete: async () => {
        const product = await k8sGetProduct();
        const flavors = new Set((product.topologies ?? []).flatMap((t) => t.availableFlavors ?? []));
        return [...flavors];
      },
    }),
    count: defineOption({
      name: 'count',
      schema: z.coerce.number().int().min(0).default(1),
      description: 'Target number of nodes',
      placeholder: 'count',
    }),
    description: k8sNodeGroupDescriptionOption,
    tag: k8sNodeGroupTagOption,
    autoscaling: k8sNodeGroupAutoscalingOption,
    min: k8sNodeGroupMinOption,
    max: k8sNodeGroupMaxOption,
    org: orgaIdOrNameOption,
    format: humanJsonOutputFormatOption,
  },
  args: [
    k8sIdOrNameArg,
    defineArgument({
      schema: z.string(),
      description: 'Node group name',
      placeholder: 'nodegroup-name',
    }),
  ],
  async handler(options, clusterIdOrName, name) {
    const { format, org: orgIdOrName } = options;

    const nodeGroup = await k8sCreateNodeGroup(orgIdOrName, clusterIdOrName, {
      name,
      flavor: options.flavor,
      targetNodeCount: options.count,
      description: options.description,
      tag: options.tag,
      autoscaling: options.autoscaling,
      min: options.min,
      max: options.max,
    });

    switch (format) {
      case 'json':
        Logger.printJson(nodeGroup);
        break;
      case 'human':
      default:
        Logger.printSuccess(`Node group ${styleText('green', `${nodeGroup.name} (${nodeGroup.id})`)} is being created`);
        break;
    }
  },
});
